import { useEffect, useRef, useState } from "react";
import { supabase } from "@/integrations/supabase/client";
import { createWorkerTicker } from "@/components/YouTubeStage";

/**
 * The only session allowed to ingest Kick requests and control the shared room
 * is a verified admin with a live, database-backed host lease.
 *
 * NOTE: Newly added table/RPC types are regenerated by Lovable after database
 * deployment; the cast below is isolated until that generated file updates.
 */
const roomDb = supabase as any;

export interface RoomHostState {
  isRoomAdmin: boolean;
  isHost: boolean;
  checking: boolean;
  error: string | null;
}

export function useRoomHost(): RoomHostState {
  const clientIdRef = useRef<string>(crypto.randomUUID());
  const [isRoomAdmin, setIsRoomAdmin] = useState(false);
  const [isHost, setIsHost] = useState(false);
  const [checking, setChecking] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    let disposed = false;
    async function checkRole() {
      const { data: userData, error: userError } = await supabase.auth.getUser();
      if (disposed) return;
      if (userError || !userData.user) {
        setIsRoomAdmin(false);
        setIsHost(false);
        setChecking(false);
        return;
      }
      const { data, error: roleError } = await roomDb
        .from("music_room_admins")
        .select("user_id")
        .eq("user_id", userData.user.id)
        .maybeSingle();
      if (disposed) return;
      const allowed = !roleError && Boolean(data);
      setIsRoomAdmin(allowed);
      setChecking(false);
      if (roleError) {
        setError("Permissões do streamer não configuradas. Consulte a administração.");
      }
    }
    void checkRole();
    const { data: authListener } = supabase.auth.onAuthStateChange(() => {
      void checkRole();
    });
    return () => {
      disposed = true;
      authListener.subscription.unsubscribe();
    };
  }, []);

  useEffect(() => {
    if (!isRoomAdmin) {
      setIsHost(false);
      return;
    }
    let disposed = false;
    let inFlight = false;

    async function renewLease() {
      if (disposed || inFlight) return;
      inFlight = true;
      try {
        const { data, error: leaseError } = await roomDb.rpc("claim_music_room_host", {
          p_client_id: clientIdRef.current,
        });
        if (disposed) return;
        setIsHost(!leaseError && data === true);
        if (leaseError) setError("Não foi possível obter o controle da sala.");
        else setError(null);
      } catch {
        if (!disposed) {
          setIsHost(false);
          setError("Falha de conexão ao verificar o host.");
        }
      } finally {
        inFlight = false;
      }
    }

    void renewLease();
    // Streamers commonly keep the player in a background tab. A worker
    // heartbeat is less affected by browser timer throttling.
    const stopTicker = createWorkerTicker(() => { void renewLease(); }, 8_000);
    const onVisible = () => { if (document.visibilityState === "visible") void renewLease(); };
    document.addEventListener("visibilitychange", onVisible);

    return () => {
      disposed = true;
      stopTicker();
      document.removeEventListener("visibilitychange", onVisible);
      void roomDb.rpc("release_music_room_host", {
        p_client_id: clientIdRef.current,
      });
    };
  }, [isRoomAdmin]);

  return { isRoomAdmin, isHost, checking, error };
}
